import React from 'react';

function App() {
    return (
        <div style={{textAlign:'center', marginTop:'50px'}}>
            <h1>🚀 سیستم مدیریت ایمنی</h1>
            <p>پروژه با موفقیت ساخته شد!</p>
            <p style={{color:'green'}}>✅ بک‌اند و فرانت‌اند آماده اجرا هستند</p>
        </div>
    );
}

export default App;
